  "site.about.clubsEyebrow": "Das Netzwerk",
  "site.about.clubsText": "Jeder Verein hat sein eigenes Zuhause und seine Gemeinschaft, mit derselben sportlichen Leitung.",
  "site.about.clubsTitle": "Unsere Vereine",
  "site.about.heroText": "Judo Arte e Vida entstand an der Algarve rund um einen Trainer und eine Idee: Judo ist viel mehr als ein Sport.",
  "site.about.heroTitle": "Eine Familie rund um die Tatami",
  "site.about.story1": "Alles beginnt mit Matias Luwawa, Judoka seit 1994. Trainer seit 2006 und Kampfrichter seit 2009, wurde er Elite-Kampfrichter und baute Dojo für Dojo ein Netzwerk von Vereinen an der Algarve auf: Lagos, Albufeira, Alvor.",
  "site.about.story2": "Heute vereint Judo Arte e Vida Vereine, Trainer, Athleten und Familien, die dieselben Werte teilen, und eine Plattform, die sie verbindet: Anmeldungen, Beiträge, Anwesenheit, Wettkämpfe und Ranking an einem Ort.",
