  "site.vision.heroText": "Wir möchten, dass jedes Kind, jede Familie und jeder Athlet im Judo Disziplin, Respekt und Freude findet: in jedem Verein des Netzwerks.",
  "site.vision.heroTitle": "Judo als Lebensschule, für alle erreichbar",
  "site.vision.mission1": "Judo hat einen moralischen Kodex: Respekt, Aufrichtigkeit, Mut, Selbstbeherrschung. Wir tragen ihn von der Tatami nach Hause, in die Schule und ins Leben.",
  "site.vision.mission2": "Und wir möchten, dass sich Vereine darauf konzentrieren können, nicht auf Bürokratie: Deshalb hat das Netzwerk eine Plattform, die Beiträge, Anwesenheit, Wettkämpfe und Finanzen von selbst erledigt.",
